using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Codice.Mechanics;using Codice.Expedition;using Codice.Bosses;
public static class BuildContentLab {
 static Material Material(string name,Color tint){string path="Assets/Resources/ExpeditionEnemies/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}m.SetColor("_BaseColor",tint);m.SetFloat("_Metallic",.35f);m.SetFloat("_Smoothness",.3f);return m;}
 static void Part(Transform parent,string name,PrimitiveType type,Vector3 position,Vector3 size,Material material){var go=GameObject.CreatePrimitive(type);go.name=name;Object.DestroyImmediate(go.GetComponent<Collider>());go.transform.SetParent(parent,false);go.transform.localPosition=position;go.transform.localScale=size;go.GetComponent<Renderer>().sharedMaterial=material;}
 static void BuildBoss(string source,string name,BossKind kind,Color tint){var root=Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/01_Prefabs/Bosses/"+source+".prefab"));root.name=name;var boss=root.GetComponent<BossCharacter>();boss.kind=kind;boss.baseHealth=kind==BossKind.StoneGuardian?1700:1400;boss.goldReward=400;boss.summons=new Codice.Enemies.BasicEnemy[0];boss.restrictToMelee=false;boss.bloodInquisitor=false;var mat=Material(name,tint);foreach(var renderer in boss.visual.GetComponentsInChildren<SkinnedMeshRenderer>())renderer.sharedMaterials=renderer.sharedMaterials.Select(_=>mat).ToArray();var bones=root.GetComponentsInChildren<Transform>();if(kind==BossKind.StoneGuardian){var chest=bones.FirstOrDefault(t=>t.name=="Character1_Ctrl_Spine2")??boss.visual;var crystal=Material("Cristal violeta",new Color(.5f,.15f,.7f));Part(chest,"Corazón mineral",PrimitiveType.Sphere,Vector3.forward*.15f,Vector3.one*.25f,crystal);}else{var metal=Material("Acero de custodio",new Color(.32f,.34f,.38f));foreach(bool left in kind==BossKind.TwinBladeWarden?new[]{true,false}:new[]{false}){var hand=bones.FirstOrDefault(t=>t.name==(left?"hand.L":"hand.R"));if(!hand)hand=bones.FirstOrDefault(t=>t.name==(left?"Character1_Ctrl_LeftHand":"Character1_Ctrl_RightHand"));if(!hand)continue;float scale=1/Mathf.Max(.01f,hand.lossyScale.x);var weapon=new GameObject(left?"Hoja izquierda":"Arma derecha");weapon.transform.SetParent(hand,false);weapon.transform.localScale=Vector3.one*scale;weapon.transform.localRotation=Quaternion.Euler(0,0,90);if(kind==BossKind.SpearWarden){Part(weapon.transform,"Asta",PrimitiveType.Cylinder,new Vector3(0,.25f,0),new Vector3(.045f,1.1f,.045f),metal);Part(weapon.transform,"Punta",PrimitiveType.Cube,new Vector3(0,1.4f,0),new Vector3(.1f,.45f,.04f),metal);}else{Part(weapon.transform,"Hoja",PrimitiveType.Cube,new Vector3(0,.55f,0),new Vector3(.16f,1.1f,.035f),metal);Part(weapon.transform,"Guarda",PrimitiveType.Cube,Vector3.zero,new Vector3(.36f,.06f,.1f),metal);}}}PrefabUtility.SaveAsPrefabAsset(root,"Assets/Resources/ExpeditionEnemies/"+name+".prefab");Object.DestroyImmediate(root);}
 public static string Run(){BuildBoss("MonsterOrc","Custodio de las dos hojas",BossKind.TwinBladeWarden,new Color(.21f,.29f,.13f));BuildBoss("MonsterOrc","Lancero de ceniza",BossKind.SpearWarden,new Color(.36f,.18f,.11f));BuildBoss("MonsterMutant","Guardian de obsidiana",BossKind.StoneGuardian,new Color(.12f,.14f,.18f));const string catPath="Assets/Resources/CindersDungeon/ContentCatalog.asset";var catalog=AssetDatabase.LoadAssetAtPath<ExpeditionContentCatalog>(catPath);if(!catalog){catalog=ScriptableObject.CreateInstance<ExpeditionContentCatalog>();AssetDatabase.CreateAsset(catalog,catPath);}
 AssetDatabase.SaveAssets();EditorSceneManager.SaveOpenScenes();var scene=EditorSceneManager.OpenScene("Assets/00_Scenes/Maps/SalaPruebas.unity");EditorSceneManager.SaveScene(scene,"Assets/00_Scenes/Maps/LaboratorioContenido.unity");catalog=AssetDatabase.LoadAssetAtPath<ExpeditionContentCatalog>(catPath);var lab=Object.FindAnyObjectByType<CombatTestRoom>();lab.enemyPrefabs=AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/Resources/ExpeditionEnemies"}).Select(g=>AssetDatabase.LoadAssetAtPath<GameObject>(AssetDatabase.GUIDToAssetPath(g))).Where(p=>p.GetComponent<Codice.Enemies.BasicEnemy>()||p.GetComponent<BossCharacter>()).ToArray();var work=new GameObject("TALLER · catálogo y decoración").AddComponent<ProceduralContentWorkbench>();work.catalog=catalog;var manual=new GameObject("CONTENIDO EDITABLE · añade tus objetos aquí");manual.transform.SetParent(work.transform,false);work.editableContent=manual.transform;
 var assets=AssetDatabase.FindAssets("barrel t:Prefab").Select(AssetDatabase.GUIDToAssetPath).Where(p=>!p.Contains("Editor")).Take(2).Select(AssetDatabase.LoadAssetAtPath<GameObject>).ToArray();if(catalog.additionalProps.Length==0)catalog.additionalProps=assets;work.GeneratePreview();EditorUtility.SetDirty(catalog);EditorSceneManager.SaveScene(scene);var builds=EditorBuildSettings.scenes.ToList();if(!builds.Any(x=>x.path==scene.path)){builds.Add(new EditorBuildSettingsScene(scene.path,true));EditorBuildSettings.scenes=builds.ToArray();}AssetDatabase.SaveAssets();Selection.activeGameObject=work.gameObject;return "LaboratorioContenido saved; editable catalog; test prefabs="+lab.enemyPrefabs.Length+"; three original warden prototypes";}
}
